); }; ```  ```ts title="src/actions.ts" auto-js // highlight-next-line type CreateTaskPayload = Pick; export const createTask: CreateTask = async ( args, context, ) => { // highlight-start if (!context.user) { throw new HttpError(401); } // highlight-end return context.entities.Task.create({ data: { description: args.description, // highlight-next-line user: { connect: { id: context.user.id } }, }, }); }; type UpdateTaskPayload = Pick; export const updateTask: UpdateTask< UpdateTaskPayload, { count: number } > = async (args, context) => { // highlight-start if (!context.user) { throw new HttpError(401); } // highlight-end return context.entities.Task.updateMany({ where: { id: args.id, user: { id: context.user.id } }, data: { isDone: args.isDone }, }); }; ```  :::note Due to how Prisma works, we had to convert `update` to `updateMany` in `updateTask` action to be able to specify the user id in `where`. ::: With these changes, each user should have a list of tasks that only they can see and edit. Try playing around, adding a few users and some tasks for each of them. Then open the DB studio: ```sh wasp db studio ``` ![Image 8: Database demonstration](https://wasp.sh/%7BuseBaseUrl('img/wasp_db_demonstration.gif')%7D) You will see that each user has their tasks, just as we specified in our code! ### Logout Button Last, but not least, let's add the logout functionality:  ```tsx title="src/MainPage.tsx" auto-js with-hole // highlight-next-line // ... existing imports export const MainPage = ({ user }: { user: AuthUser }) => { // ... return ( 

